-- Разбор реального прогона: replyToSeq указывал на pin_message — формально
-- валидно (структурная проверка это пропускала), но pin_message рендерится
-- отдельным закреплённым баннером сверху экрана, а не обычным пузырём в
-- ленте, поэтому цитата "в ответ на" ссылалась на текст, которого нигде
-- нет среди обычных сообщений чата ("ссылка в никуда"). Дополнено правило.
--
-- Отдельно: пользователь настоял, что нода-реакция (эмоция без содержания)
-- никогда не должна быть голым эмодзи — только текст в стиле чат-привычек
-- альфа/зумеров ("Да)", "Огонь))"). Раньше правило говорило "иногда можно"
-- как один из вариантов — теперь для ЭТОГО конкретного случая (отдельная
-- нода-реакция) это ОБЯЗАТЕЛЬНО, а не один из вариантов.
--
-- Проверено на конфликт: апдейты целятся в старые формулировки по WHERE,
-- идемпотентно.
update public.lesson_rules
set rule_text = 'replyToSeq должен указывать на ноду, у которой ЕСТЬ читаемое содержимое (текст/собранная фраза), — никогда на reaction/system/pin_message: у reaction/system нет текста для цитаты вовсе (цитата отрендерится пустой — виден только «Вы:»/имя без текста); pin_message формально текст ИМЕЕТ, но рендерится не как обычный пузырь в ленте, а отдельным закреплённым баннером сверху экрана — цитата на него технически покажет текст, но этого текста нигде не будет видно СРЕДИ обычных сообщений чата, и это читается как «ссылка в никуда». После КАЖДОЙ правки графа (сплайс, новые ноды, сигналы) пересчитывай реальный seq (см. computeSeqMap в nodeGraph.js) для каждого узла с replyToSeq — старое число могло стать нерабочим, даже если сам узел не менялся. Мало проверить, что seq структурно существует и не указывает на reaction/system/pin_message — нужно ещё прочитать содержимое цели и убедиться, что оно СМЫСЛОВО относится к тому, что говорит цитирующая нода (обычно это соседняя по графу нода на расстоянии в 1-3 шага). Симптом такого бага: цитата ссылается на ответ/фразу из СОВСЕМ ДРУГОГО, более раннего упражнения, никак не связанного с текущей репликой.'
where rule_text like 'replyToSeq должен указывать%'
  and rule_text not like '%pin_message%';

update public.lesson_rules
set rule_text = 'Отдельная нода-РЕАКЦИЯ (короткая текстовая нода-подтверждение, которая не несёт ничего кроме эмоции — «одобрение», «в точку» и т.п.) НИКОГДА не состоит из одного голого эмодзи ("🔥", "🙌", "😍" сами по себе) — только текст в духе чат-привычек поколения альфа/зумеров: одинарная/двойная закрывающая скобка вместо смайла («Да)», «Огонь))», «Красава)»), «ору» или «кек» как маркер «это смешно», нарочито растянутое слово («не-е-ет»), эмодзи 😭 в ироничном смысле (не «плачу», а «это перебор/очень смешно»). Эмодзи ВНУТРИ обычного сообщения с текстом (в конце фразы, как акцент — «Собери: «Он пробует торт» 🎂🤤») — это другое, так делать можно и нужно. Не переусердствуй с «))»/«ору» — если они в КАЖДОМ сообщении, это тоже читается неестественно, как переигрывание; варьируй конкретные слова/пунктуацию от реплики к реплике.'
where rule_text like 'Иногда (не в каждой реплике%'
  and rule_text not like '%НИКОГДА не состоит из одного голого эмодзи%';
